"""Site customization for the embedded CampusBot Python runtime.

The bundled python311._pth restricts sys.path to the runtime directory
only. This module adds the current working directory to sys.path so that
project modules (e.g. ``app``) are importable when running tests or the
application from the CampusBot/ folder.

Loaded automatically because python311._pth contains ``import site``.
"""

import os
import sys

# Insert the current working directory at the front of sys.path so that
# `app`, `tests`, and other project packages resolve correctly.
_cwd = os.getcwd()
if _cwd not in sys.path:
    sys.path.insert(0, _cwd)
